/**
 * Milestone state conflicts: a closed milestone used where an open one is
 * required, reopening an open one, the open-milestone cap, and a taken name.
 *
 * `toAppError` maps this class to `conflict`.
 */

export type MilestoneStateReason =
  | "closed"
  | "already_open"
  | "too_many_open"
  | "name_taken";

const MESSAGES: Readonly<Record<MilestoneStateReason, string>> = {
  closed: "That milestone is closed.",
  already_open: "That milestone is already open.",
  too_many_open: "This project already has the maximum number of open milestones.",
  name_taken: "A milestone with that name already exists in this project.",
};

export class MilestoneStateError extends Error {
  readonly code = "conflict" as const;
  readonly reason: MilestoneStateReason;

  constructor(reason: MilestoneStateReason) {
    super(MESSAGES[reason]);
    this.name = "MilestoneStateError";
    this.reason = reason;
  }
}

/**
 * Identity used for uniqueness: letter case and surrounding spaces do not
 * count, and closed milestones still occupy the name.
 */
export function milestoneNameKey(name: string): string {
  return name.trim().toLowerCase();
}

import type {
  IsoTimestamp,
  MilestoneId,
  ProjectId,
  TenantScoped,
  Timestamps,
} from "./common";

export interface Milestone extends Timestamps, TenantScoped {
  readonly id: MilestoneId;
  readonly projectId: ProjectId;
  readonly name: string;
  readonly targetDate: IsoTimestamp | null;
  readonly closedAt: IsoTimestamp | null;
}

export interface MilestoneProgress {
  readonly total: number;
  readonly open: number;
  readonly closed: number;
}

export interface MilestoneWithProgress {
  readonly milestone: Milestone;
  readonly progress: MilestoneProgress;
  readonly overdue: boolean;
}

import { z } from "zod";
import {
  isoTimestampSchema,
  issueIdSchema,
  milestoneIdSchema,
  orgIdSchema,
  projectIdSchema,
} from "./common";

export const createMilestoneSchema = z.object({
  orgId: orgIdSchema,
  projectId: projectIdSchema,
  name: z.string().min(1).max(80),
  targetDate: isoTimestampSchema.nullable().default(null),
});

export const updateMilestoneSchema = z.object({
  orgId: orgIdSchema,
  milestoneId: milestoneIdSchema,
  name: z.string().min(1).max(80).optional(),
  targetDate: isoTimestampSchema.nullable().optional(),
});

export const closeMilestoneSchema = z.object({
  orgId: orgIdSchema,
  milestoneId: milestoneIdSchema,
  moveOpenIssuesTo: milestoneIdSchema.nullable().default(null),
});

export const setIssueMilestoneSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
  milestoneId: milestoneIdSchema.nullable(),
});

export type CreateMilestoneInput = z.infer<typeof createMilestoneSchema>;
export type UpdateMilestoneInput = z.infer<typeof updateMilestoneSchema>;
export type CloseMilestoneInput = z.infer<typeof closeMilestoneSchema>;
export type SetIssueMilestoneInput = z.infer<typeof setIssueMilestoneSchema>;

import { index, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns, timestampColumns } from "./_shared";

export const milestones = sqliteTable(
  "milestones",
  {
    id: idColumn(),
    ...tenantColumns,
    projectId: text("project_id").notNull(),
    name: text("name").notNull(),
    /** `trim + lower` of `name`, so uniqueness ignores case and surrounding spaces. */
    nameKey: text("name_key").notNull(),
    targetDate: text("target_date"),
    closedAt: text("closed_at"),
    ...timestampColumns,
  },
  (table) => [
    uniqueIndex("milestones_project_name_key_idx").on(table.projectId, table.nameKey),
    index("milestones_org_project_idx").on(table.orgId, table.projectId),
  ],
);

export type MilestoneRow = typeof milestones.$inferSelect;
export type NewMilestoneRow = typeof milestones.$inferInsert;

