/**
 * Milestone rows for one project. Names are unique per project via `name_key`
 * (case and surrounding spaces ignored), including closed milestones.
 */
import { and, count, eq, inArray, isNull } from "drizzle-orm";
import { newId } from "@/lib/id";
import { milestoneNameKey } from "@/lib/milestones";
import { getDb, issues, milestones } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact } from "./_paging";
import { toMilestone } from "./_mappers";
import type { CreateMilestoneInput, UpdateMilestoneInput } from "@/schemas/milestone";
import type { IsoTimestamp, IssueId, MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { Milestone, MilestoneProgress } from "@/types/milestone";

const OPEN_ISSUE_STATUSES = [
  "backlog",
  "todo",
  "in_progress",
  "in_review",
] as const;

export async function findMilestoneById(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)))
    .get();
  return row ? toMilestone(row) : null;
}

export async function findMilestoneByNameKey(
  orgId: OrgId,
  projectId: ProjectId,
  nameKey: string,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
        eq(milestones.nameKey, nameKey),
      ),
    )
    .get();
  return row ? toMilestone(row) : null;
}

export async function listMilestonesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Milestone[]> {
  const rows = getDb()
    .select()
    .from(milestones)
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.projectId, projectId)),
    )
    .all();
  return rows.map(toMilestone);
}

export async function countOpenMilestones(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
        isNull(milestones.closedAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertMilestone(
  input: CreateMilestoneInput,
): Promise<Milestone> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(milestones)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      name: input.name,
      nameKey: milestoneNameKey(input.name),
      targetDate: input.targetDate,
      closedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
  return toMilestone(row);
}

export async function updateMilestone(
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({
      ...(input.name === undefined
        ? {}
        : { name: input.name, nameKey: milestoneNameKey(input.name) }),
      ...(input.targetDate === undefined ? {} : { targetDate: input.targetDate }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(milestones.orgId, input.orgId),
        eq(milestones.id, input.milestoneId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${input.milestoneId} not found`);
  return toMilestone(row);
}

export async function markMilestoneClosed(
  orgId: OrgId,
  milestoneId: MilestoneId,
  closedAt: IsoTimestamp,
): Promise<Milestone> {
  const row = getDb()
    .update(milestones)
    .set({ closedAt, updatedAt: closedAt })
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.id, milestoneId),
        isNull(milestones.closedAt),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

export async function markMilestoneOpen(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(milestones)
    .set({ closedAt: null, updatedAt: stamp })
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Milestone ${milestoneId} not found`);
  return toMilestone(row);
}

/**
 * Live, still-open issues on a milestone. Closed and archived issues stay
 * put when the milestone closes, so they are not part of this set.
 */
export async function listOpenLiveIssueIds(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ id: issues.id })
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.milestoneId, milestoneId),
          livePredicate(issues.archivedAt, {}),
          inArray(issues.status, [...OPEN_ISSUE_STATUSES]),
        ),
      ),
    )
    .all();
  return rows.map((row) => row.id as IssueId);
}

export async function moveIssuesToMilestone(
  orgId: OrgId,
  issueIds: readonly IssueId[],
  milestoneId: MilestoneId | null,
): Promise<void> {
  if (issueIds.length === 0) return;
  const stamp = toIsoTimestamp(new Date());
  getDb()
    .update(issues)
