/**
 * Closes a milestone and moves its open live issues in one transaction.
 * Closed and archived issues are left on the milestone. A milestone that is
 * already closed updates nothing and throws.
 */
export async function closeMovingOpenIssues(
  orgId: OrgId,
  milestoneId: MilestoneId,
  moveTo: MilestoneId | null,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  const stamp = toIsoTimestamp(new Date());
  return getDb().transaction((tx) => {
    const openRows = tx
