/**
 * Milestone lifecycle for a project: create, rename, retarget, close, reopen and list.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, assertNotArchived
 */
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { isOverdue } from "@/lib/date";
import { emit } from "@/lib/event-bus";
import { MilestoneStateError, milestoneNameKey } from "@/lib/milestones";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as activityService from "@/server/services/activity-service";
import * as milestoneRepo from "@/server/repositories/milestone-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import {
  actorEnvelope,
  NotFoundError,
  projectResource,
  requireFound,
} from "./_support";
import type {
  CloseMilestoneInput,
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type { MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { Actor } from "@/types/member";
import type {
  Milestone,
  MilestoneProgress,
  MilestoneWithProgress,
} from "@/types/milestone";
import type { Project } from "@/types/project";

const EMPTY_PROGRESS: MilestoneProgress = { total: 0, open: 0, closed: 0 };

function isNameConflict(error: unknown): boolean {
  return (
    typeof error === "object" &&
    error !== null &&
    "code" in error &&
    (error as { code: unknown }).code === "SQLITE_CONSTRAINT_UNIQUE"
  );
}

/**
 * An open milestone of `projectId` in this workspace. Anything else — missing,
 * another project, another workspace — is `NotFoundError`. A closed one is
 * `MilestoneStateError`.
 */
export async function requireOpenMilestone(
  orgId: OrgId,
  projectId: ProjectId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  if (milestone.projectId !== projectId) {
    throw new NotFoundError("Milestone", milestoneId);
  }
  if (milestone.closedAt !== null) {
    throw new MilestoneStateError("closed");
  }
  return milestone;
}

async function requireWritableProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);
  return project;
}

async function assertNameAvailable(
  orgId: OrgId,
  projectId: ProjectId,
  name: string,
  exceptId?: MilestoneId,
): Promise<void> {
  const existing = await milestoneRepo.findMilestoneByNameKey(
    orgId,
    projectId,
    milestoneNameKey(name),
  );
  if (existing !== null && existing.id !== exceptId) {
    throw new MilestoneStateError("name_taken");
  }
}

async function assertOpenCap(orgId: OrgId, projectId: ProjectId): Promise<void> {
  const open = await milestoneRepo.countOpenMilestones(orgId, projectId);
  if (open >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open");
  }
}

function compareMilestones(a: Milestone, b: Milestone): number {
  const aClosed = a.closedAt === null ? 0 : 1;
  const bClosed = b.closedAt === null ? 0 : 1;
  if (aClosed !== bClosed) return aClosed - bClosed;

  if (a.targetDate === null && b.targetDate !== null) return 1;
  if (a.targetDate !== null && b.targetDate === null) return -1;
  if (a.targetDate !== null && b.targetDate !== null && a.targetDate !== b.targetDate) {
    return a.targetDate < b.targetDate ? -1 : 1;
  }

  if (a.createdAt !== b.createdAt) return a.createdAt < b.createdAt ? -1 : 1;
  return a.id < b.id ? -1 : 1;
}

function withProgress(
  milestone: Milestone,
  progress: MilestoneProgress,
  now: Date,
): MilestoneWithProgress {
  return {
    milestone,
    progress,
    overdue:
      milestone.closedAt === null &&
      progress.open > 0 &&
      isOverdue(milestone.targetDate, now),
  };
}

async function decorate(
  orgId: OrgId,
  milestones: readonly Milestone[],
): Promise<readonly MilestoneWithProgress[]> {
  const progress = await milestoneRepo.progressForMilestones(
    orgId,
    milestones.map((milestone) => milestone.id),
  );
  const now = new Date();
  return milestones.map((milestone) =>
    withProgress(milestone, progress.get(milestone.id) ?? EMPTY_PROGRESS, now),
  );
}

export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);
  await requireWritableProject(actor, input.orgId, input.projectId);
  await assertNameAvailable(input.orgId, input.projectId, input.name);
  await assertOpenCap(input.orgId, input.projectId);

  let milestone: Milestone;
  try {
    milestone = await milestoneRepo.insertMilestone(input);
  } catch (error) {
    if (isNameConflict(error)) throw new MilestoneStateError("name_taken");
    throw error;
  }

  await activityService.record(input.orgId, "milestone.created", {
    actorId: actor.userId,
    subjectKind: "milestone",
    subjectId: milestone.id,
    projectId: milestone.projectId,
    summary: `Created milestone ${milestone.name}`,
  });

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);

  const current = requireFound(
    await milestoneRepo.findMilestoneById(input.orgId, input.milestoneId),
    "Milestone",
    input.milestoneId,
  );
  await requireWritableProject(actor, input.orgId, current.projectId);

  if (input.name !== undefined) {
    await assertNameAvailable(
      input.orgId,
      current.projectId,
      input.name,
      current.id,
    );
  }

  try {
    return await milestoneRepo.updateMilestone(input);
  } catch (error) {
    if (isNameConflict(error)) throw new MilestoneStateError("name_taken");
    throw error;
  }
}

export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const current = requireFound(
    await milestoneRepo.findMilestoneById(input.orgId, input.milestoneId),
    "Milestone",
    input.milestoneId,
  );
  await requireWritableProject(actor, input.orgId, current.projectId);

  if (current.closedAt !== null) {
    throw new MilestoneStateError("closed");
  }

  const moveTo = input.moveOpenIssuesTo;
  if (moveTo !== null) {
    if (moveTo === current.id) {
      throw new NotFoundError("Milestone", moveTo);
    }
    const target = requireFound(
      await milestoneRepo.findMilestoneById(input.orgId, moveTo),
      "Milestone",
      moveTo,
    );
    if (target.projectId !== current.projectId) {
      throw new NotFoundError("Milestone", moveTo);
    }
    if (target.closedAt !== null) {
      throw new MilestoneStateError("closed");
    }
  }

  const { milestone, movedIssueIds } = await milestoneRepo.closeMovingOpenIssues(
    input.orgId,
    current.id,
    moveTo,
  );

  await activityService.record(input.orgId, "milestone.closed", {
    actorId: actor.userId,
    subjectKind: "milestone",
    subjectId: milestone.id,
    projectId: milestone.projectId,
    summary: `Closed milestone ${milestone.name}`,
    metadata: {
      movedToMilestoneId: moveTo,
      movedCount: movedIssueIds.length,
    },
  });

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
    movedToMilestoneId: moveTo,
    movedIssueIds,
  });

  return { milestone, movedIssueIds };
}

export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  assertOrgScope(actor, orgId);

  const current = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  await requireWritableProject(actor, orgId, current.projectId);

  if (current.closedAt === null) {
    throw new MilestoneStateError("already_open");
  }
  await assertOpenCap(orgId, current.projectId);

  const milestone = await milestoneRepo.markMilestoneOpen(orgId, milestoneId);

  await activityService.record(orgId, "milestone.reopened", {
    actorId: actor.userId,
    subjectKind: "milestone",
    subjectId: milestone.id,
    projectId: milestone.projectId,
    summary: `Reopened milestone ${milestone.name}`,
  });

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:read", projectResource(project));

  const milestones = [...(await milestoneRepo.listMilestonesForProject(orgId, projectId))];
  milestones.sort(compareMilestones);
  return decorate(orgId, milestones);
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(orgId, milestone.projectId),
    "Project",
    milestone.projectId,
  );
  assertCan(actor, "project:read", projectResource(project));

  const [decorated] = await decorate(orgId, [milestone]);
  if (!decorated) throw new NotFoundError("Milestone", milestoneId);
  return decorated;
}

